//! Golden parity tests against wordsegment 1.3.1.
//!
//! Fixtures are generated by `parity/gen_fixtures.py`. Regenerate them with
//! `pixi run --manifest-path crates/ports/wordsegment/pixi.toml fixtures`.

use serde::Deserialize;
use wordsegment::Segmenter;

const SEGMENT: &str = include_str!("fixtures/segment.jsonl");
const SCORE: &str = include_str!("fixtures/score.jsonl");
const DIVIDE: &str = include_str!("fixtures/divide.jsonl");
const META: &str = include_str!("fixtures/meta.json");

#[derive(Deserialize)]
struct SegmentCase {
  text: String,
  clean: String,
  segment: Vec<String>,
}

#[derive(Deserialize)]
struct ScoreCase {
  word: String,
  previous: Option<String>,
  bits: String,
}

#[derive(Deserialize)]
struct DivideCase {
  text: String,
  limit: usize,
  divide: Vec<(String, String)>,
}

#[derive(Deserialize)]
struct Meta {
  unigrams_len: usize,
  bigrams_len: usize,
  words_len: usize,
  words_head: Vec<String>,
  words_tail: Vec<String>,
  words_sample: Vec<(usize, String)>,
  total_bits: String,
  limit: usize,
}

fn loaded() -> Segmenter {
  let mut s = Segmenter::new();
  s.load();
  s
}

fn lines<'a, T: Deserialize<'a>>(data: &'a str) -> Vec<T> {
  data
    .lines()
    .filter(|l| !l.is_empty())
    .map(|l| serde_json::from_str(l).unwrap())
    .collect()
}

fn bits(x: f64) -> String {
  format!("{:016x}", x.to_bits())
}

#[test]
fn segment_parity() {
  let s = loaded();
  let cases: Vec<SegmentCase> = lines(SEGMENT);
  assert!(cases.len() >= 5000, "{} cases", cases.len());
  let mut mismatches = Vec::new();
  for case in &cases {
    assert_eq!(
      Segmenter::clean(&case.text),
      case.clean,
      "clean({:?})",
      case.text
    );
    let got = s.segment(&case.text);
    if got != case.segment {
      mismatches.push(format!(
        "{:?}: got {:?}, want {:?}",
        case.text, got, case.segment
      ));
    }
  }
  eprintln!(
    "segment: {} cases, {} exact",
    cases.len(),
    cases.len() - mismatches.len()
  );
  assert!(
    mismatches.is_empty(),
    "mismatches:\n{}",
    mismatches.join("\n")
  );
}

#[test]
fn score_parity() {
  let s = loaded();
  let cases: Vec<ScoreCase> = lines(SCORE);
  let mut mismatches = Vec::new();
  for case in &cases {
    let got = bits(s.score(&case.word, case.previous.as_deref()));
    if got != case.bits {
      mismatches.push(format!(
        "score({:?}, {:?}): got {got}, want {}",
        case.word, case.previous, case.bits
      ));
    }
  }
  eprintln!(
    "score: {} cases, {} exact",
    cases.len(),
    cases.len() - mismatches.len()
  );
  assert!(
    mismatches.is_empty(),
    "mismatches:\n{}",
    mismatches.join("\n")
  );
}

#[test]
fn divide_parity() {
  let cases: Vec<DivideCase> = lines(DIVIDE);
  for case in &cases {
    let mut s = Segmenter::new();
    s.limit = case.limit;
    let got: Vec<(String, String)> = s
      .divide(&case.text)
      .map(|(a, b)| (a.to_owned(), b.to_owned()))
      .collect();
    assert_eq!(
      got, case.divide,
      "divide({:?}, limit={})",
      case.text, case.limit
    );
  }
}

#[test]
fn load_parity() {
  let meta: Meta = serde_json::from_str(META).unwrap();
  let s = loaded();
  assert_eq!(s.unigrams.len(), meta.unigrams_len);
  assert_eq!(s.bigrams.len(), meta.bigrams_len);
  assert_eq!(s.words.len(), meta.words_len);
  assert_eq!(s.words[..meta.words_head.len()], meta.words_head[..]);
  assert_eq!(
    s.words[s.words.len() - meta.words_tail.len()..],
    meta.words_tail[..]
  );
  for (i, w) in &meta.words_sample {
    assert_eq!(&s.words[*i], w);
  }
  assert_eq!(bits(s.total), meta.total_bits);
  assert_eq!(s.limit, meta.limit);
}

#[test]
fn module_level_functions() {
  wordsegment::load();
  assert_eq!(
    wordsegment::segment("thisisatest"),
    ["this", "is", "a", "test"]
  );
  assert_eq!(
    wordsegment::isegment("choosespain").collect::<Vec<_>>(),
    ["choose", "spain"]
  );
  assert_eq!(wordsegment::clean("Don't STOP!"), "dontstop");
  let meta: Meta = serde_json::from_str(META).unwrap();
  assert!(wordsegment::UNIGRAMS().len() >= meta.unigrams_len);
  assert!(wordsegment::BIGRAMS().len() >= meta.bigrams_len);
  assert!(wordsegment::WORDS().len() >= meta.words_len);
}

#[test]
fn load_twice_extends_words() {
  // Python: `load()` extends `words` again and re-updates the dicts.
  let mut s = loaded();
  let words = s.words.len();
  let unigrams = s.unigrams.len();
  s.load();
  assert_eq!(s.words.len(), 2 * words);
  assert_eq!(s.unigrams.len(), unigrams);
}

#[test]
#[should_panic(expected = "ZeroDivisionError")]
fn score_unloaded_raises() {
  // Python: `Segmenter().score('a')` raises ZeroDivisionError.
  Segmenter::new().score("a", None);
}

#[test]
#[should_panic(expected = "OverflowError")]
fn score_overlong_word_raises() {
  // Python: `score('a' * 309)` raises OverflowError converting 10 ** 309.
  loaded().score(&"q".repeat(309), None);
}

#[test]
#[should_panic(expected = "ValueError")]
fn search_with_zero_limit_raises() {
  // Python: `max()` of no candidates raises ValueError.
  let mut s = loaded();
  s.limit = 0;
  s.segment("abc");
}
